<?php require dirname(__DIR__).'/includes/bootstrap.php';$u=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);$p=db_one("SELECT * FROM hoa_don WHERE ma_hoa_don=? AND trang_thai='SUCCESS'",[get('id')]);must((bool)$p,'Không có biên lai hợp lệ.',404);$h=contract($p['so_hop_dong'],$u);page_start('Biên lai giao dịch nội bộ');echo '<div class="panel"><h2>'.e($p['ma_hoa_don']).'</h2><p>Hợp đồng: '.e($h['so_hop_dong']).'</p><p>'.badge($p['loai_giao_dich']).' · '.e($p['ngay_thu']).'</p><p class="price">'.e(money($p['so_tien_thu'])).'</p><p>Nội dung: '.e($p['noi_dung_thu']).'</p><p>Phương thức: '.e($p['phuong_thuc_tt']).'</p><p>Nguồn / tham chiếu: '.e($p['nguon_tham_chieu'].' / '.$p['ma_tham_chieu']).'</p><p class="muted">Biên lai nội bộ của hệ thống; không thay thế hóa đơn điện tử thuế.</p><button onclick="window.print()" class="no-print">In / Lưu PDF</button></div>';page_end();
